<script setup>
const {t} = useI18n()
const state = useStreakFreezeState()
const modals = useModalStore()
const challenges = useChallengesStore()
const saveBarPreview = useState('streakSaveBarPreview', () => false)

if (import.meta.client) {
    window.__showStreakFreeze = () => {
        state.value = {missedDay: challenges.todayKey, priorStreak: 7, target: 3}
        saveBarPreview.value = true
        modals.open(STREAK_FREEZE_MODAL_ID)
    }
    window.__hideStreakFreeze = () => dismissStreakFreeze()
    if (new URLSearchParams(window.location.search).has('showStreakFreeze')) {
        onMounted(() => window.__showStreakFreeze())
    }
}

const target = computed(() => state.value?.target ?? 3)
const prior = computed(() => state.value?.priorStreak ?? 0)
const done = computed(() => Math.min(challenges.freezeProgress?.current ?? 0, target.value))
const earned = computed(() => (challenges.freezeProgress?.complete ?? false) || !challenges.freezeOffer)

watch(() => modals.isOpen(STREAK_FREEZE_MODAL_ID), (open) => {
    if (!open && state.value) dismissStreakFreeze()
})
</script>

